                    out.extend(collect_positions(v))
        return out

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        if dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        if dy > 1:
